package com.nextrade.persistence.repository; import com.nextrade.persistence.entity.TradeEntity; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.data.jpa.repository.Modifying; import org.springframework.data.jpa.repository.Query; import org.springframework.data.repository.query.Param; import java.util.*; import java.time.*; public interface TradeJpaRepository extends JpaRepository<TradeEntity,UUID> { List<TradeEntity> findByBuyOrderIdOrSellOrderId(UUID buyOrderId,UUID sellOrderId); List<TradeEntity> findByInstrumentIdOrderBySequenceAsc(UUID instrumentId); }